export const WBAFileSchema = wire(z.object({ "keys": z.array(z.object({ "alg": z.string().describe("Signing algorithm. RAMP v1.0: MUST be \"EdDSA\".").default(""), "crv": z.string().describe("Curve. RAMP v1.0: MUST be \"Ed25519\".").default(""), "kty": z.string().describe("Key type. RAMP v1.0: MUST be \"OKP\".").default(""), "not_after": z.string().describe("RFC3339 timestamp. Key is invalid at and after this instant\n (strict upper bound).").default(""), "not_before": z.string().describe("RFC3339 timestamp. Key is invalid before this instant.").default(""), "use": z.string().describe("Intended key use. RAMP v1.0: MUST be \"sig\".").default(""), "x": z.string().describe("base64url-encoded 32-byte Ed25519 public key.").default("") }).describe("JsonWebKey — Inline RFC 7517 JWK object.\n\nRAMP v1.0 supports Ed25519 only: kty=\"OKP\", crv=\"Ed25519\", alg=\"EdDSA\".\n Additional curves are a later concern.\n\n Time bounds are RFC3339 strings (sortable, ops-debuggable, avoids the\n JWT nbf/exp collision). At least one key in the served key set (WBAFile.keys)\n MUST have `not_before <= now < not_after`. Verification MUST reject\n signatures whose key falls outside its window.\n\n Keys carry no `kid`: the RFC 9421 keyid is the RFC 7638 JWK Thumbprint,\n computed locally by the verifier. Carrying a kid alongside the thumbprint\n created a drift surface and is removed.")).describe("RFC 7517 JWK Set \"keys\" member. RAMP v1: Ed25519 (OKP) keys, each with\n not_before/not_after RAMP extension members.").optional(), "revocation_url": z.string().describe("Directory-level emergency revocation channel. One per directory; the list\n it points to enumerates revoked key thumbprints. Consumers poll on a 300s\n cadence (±10% jitter) and replace their local revoked set with the response.").optional() }).describe("WBAFile — Pure Web Bot Auth directory served at the WBA-canonical well-known\n path (/.well-known/http-message-signatures-directory). A JOSE JWK Set per\n RFC 7517 §5 plus a directory-level revocation pointer. JWKs carry no kid; the\n RFC 9421 keyid is the RFC 7638 JWK Thumbprint. Off-the-shelf WBA verifiers\n read the `keys` array and ignore RAMP's extra members (per-key\n not_before/not_after, and revocation_url) per RFC 7517 §5."));

export const WellKnownManifestSchema = wire(z.object({ "accepted_verifiers": z.array(z.string()).describe("Exchange-only. Trusted attestation verification vendors (domains).").optional(), "account_registration": z.object({ "data_schema": z.record(z.string(), z.any()).describe("JSON Schema (draft 2020-12) describing the RegisterRequest.registration_data\n object this Exchange expects. This field is the single home of the\n enforce/pass-through contract, and publishing it IS the enforcement switch.\n Present: this Exchange validates registration_data against the schema and\n refuses a non-conforming payload with\n REGISTRATION_FAILURE_REASON_INVALID_REGISTRATION_DATA, naming the offending\n members in RegistrationFailure.field_errors. Absent: registration_data is\n passed through to the system of record uninspected, so an Exchange that\n publishes no schema needs no change to stay conformant.\n\nThe gate above runs on ACCOUNT CREATION ONLY. A repeat registration, for an\n agent that already holds an account, is answered from the stored record and\n runs no schema check at all — it discards registration_data rather than\n validating it. That exception is stated here rather than left to the section\n above, because this field calls itself the single home of the contract and a\n reader who comes here for the whole rule would otherwise leave with the wrong\n one. See \"Repeat registration\" in the Agent Account Registration section for\n why, and for the other gates it applies to.\n\n Absent means the field carries no bytes, or only JSON whitespace — space, tab,\n carriage return and line feed, RFC 8259's four and no others. Nothing else\n counts, and the distinction is load-bearing rather than pedantic: this is the\n enforcement switch, so a byte sequence read as absent is one that turns\n validation OFF. A consumer that asked its own language what \"blank\" means got\n three different answers to the same document — U+00A0 and U+3000 are whitespace\n to some runtimes and not others, and a decoder that strips a byte order mark\n makes a mark followed by a space look like nothing at all. A document that is\n not empty and not JSON is malformed, which is a refusal; it is never silence.\n\n Safety rules, because a consumer reads this schema out of a THIRD PARTY's\n manifest and validates against it before any signature has been checked. A\n publisher MUST satisfy every rule below and a consumer MUST refuse a schema\n that does not. The bounds are stated here as numbers rather than left to each\n implementation on purpose: a schema is validated at both ends of the same\n registration, and a limit chosen privately by one side refuses payloads the\n other accepts.\n\n   Self-contained. Every $ref, $dynamicRef and $recursiveRef MUST be a\n   same-document reference — it begins with \"#\". A consumer MUST NOT resolve a\n   reference that leaves the document: doing so turns every reader into an\n   SSRF vector aimed at a URL the schema's author chose.\n\n   One dialect. $schema, wherever it appears in the document, MUST name\n   https://json-schema.org/draft/2020-12/schema (an empty fragment on the end\n   is the same value). A document declaring none is read as that dialect. An\n   older draft is refused rather than validated under semantics its author did\n   not intend.\n\n   Data is not schema. `const`, `enum`, `default` and `examples` hold arbitrary\n   JSON VALUES, and their contents are never read as keywords: a `const` whose\n   value happens to carry a \"$ref\" or \"$schema\" member states a value a payload\n   may equal, not a reference to resolve or a dialect to honour. Both rules\n   above therefore stop at those four keywords, and so does the pattern\n   alphabet. Their nesting still counts against the depth cap. Likewise the\n   child keys of `properties`, `patternProperties`, `$defs`, `definitions` and\n   `dependentSchemas` are NAMES rather than keywords, so a property called\n   \"$ref\" is a property.\n\n   Bounded size: 16KB, measured as the UTF-8 bytes of this member AS SERVED in\n   ramp.json.\n\n   One encoding. The bytes MUST be well-formed UTF-8 (RFC 8259 requires it for\n   interchange) and MUST NOT begin with a byte order mark. RFC 8259 forbids\n   ADDING a mark and lets a parser ignore one, so both policies conform and the\n   choice is made here rather than left to each implementation: parsers differ,\n   and one that strips a mark validates a different document — and counts three\n   bytes against the size cap that the schema does not contain. A consumer MUST\n   NOT repair ill-formed bytes either; substituting U+FFFD silently enforces a\n   schema nobody published. A mark is in any case only valid at the start of a\n   JSON text, and this is a member inside one.\n\n   Bounded depth: 32 nested JSON containers, counting the schema itself as the\n   first.\n\n   Bounded WORK: 10000 evaluations, counted statically over the SCHEMA — each\n   anyOf/oneOf/allOf branch and prefixItems entry costs its own subschema, and a\n   $ref costs its target. It is the cost of applying the schema at ONE location\n   in a payload, not of a whole payload: a subschema under `items` is counted\n   once here and evaluated once per element at runtime. The size and depth caps\n   do not bound it and are not a substitute for it: branches multiply along a\n   reference chain, so a 1.6KB schema five containers deep can cost tens of\n   millions of evaluations and tens of seconds against a two-member payload. A\n   definition nobody references costs nothing, so a document may carry a library\n   of them.\n\n   Bounded reference chains: 100 hops, counted as the longest path of $ref hops\n   rather than as the number of references the document contains. This is a\n   THIRD axis, and a flat chain of definitions shows why it has to be: each one\n   referring to the next is three JSON containers deep however long it is, so\n   the depth cap never sees it, and it costs one evaluation per link, so the\n   work cap does not either. What it does reach is the recursion a validator\n   performs while resolving the chain — a chain of a few hundred exhausted one\n   implementation's stack outright, on a document every other rule had passed.\n   A schema describing a business entity chains one or two references.\n\n   No reference cycles. A $ref chain MUST NOT return to a schema already on it.\n   The construct is legal JSON Schema and is how a recursive structure is\n   written, but its evaluation cost has no static bound and it is what makes a\n   validator recurse until it aborts. Registration data describes a business\n   entity, which is not a recursive shape.\n\n   A portable `pattern` alphabet, stated as what a pattern MAY contain rather\n   than as what it may not. A group MUST open with \"(\" or \"(?:\" and nothing\n   else; only the escapes \\$, \\(, \\), \\*, \\+, \\., \\/, \\?, \\D, \\W, \\[, \\\\, \\],\n   \\^, \\d, \\f, \\n, \\r, \\t, \\v, \\w, \\{, \\| and \\} MAY appear, together with \\xHH\n   carrying exactly two hexadecimal digits (spelled out rather than ranged, so a\n   conformance guard can check the set character by character); a counted repeat\n   MUST NOT exceed 1000 and MUST state its first bound, so \"a{2,}\" is admitted\n   and \"a{,5}\" is not; a \"}\" outside a bracket expression MUST close a counted\n   repeat, so a literal brace is written \"\\}\"; \"[:\" MUST NOT appear inside a\n   bracket expression; a bracket expression MUST close and MUST NOT open with\n   \"]\"; and a range endpoint MUST NOT be one of the shorthand classes (\"[\\w-x]\").\n\n   The two brace rules are there for the same reason as the bracket ones, and\n   were found the same way. \"a{,5}\" is five literal characters to RE2 and a\n   repeat of zero to five to Python, so both engines compile it and then\n   disagree about which payloads match — the silent kind. An unmatched \"}\" is a\n   literal to RE2 and to Python and a syntax error to ECMA-262 under the `u`\n   flag, which is the loud kind, and exactly what the unmatched \"]\" rule above\n   already refuses.\n\n   The direction of that rule is the rule. Draft 2020-12 patterns are ECMA-262,\n   but the engines implementations run do not agree on it, and the set they\n   disagree about has no end: it grows with every dialect and every library\n   version, so a list of forbidden escapes needs a new entry each time somebody\n   finds one, and until then the gap is open. The portable set is small and\n   closed, and an author who wants a construct outside it writes the characters\n   out instead.\n\n   Some of the disagreement is loud — RE2 refuses the lookaround, atomic groups\n   and backreferences ECMA allows, so a schema using them compiles for one\n   implementation and fails for another. The rest is SILENT, and is why this is\n   a MUST rather than a SHOULD: inline flags, Unicode property classes, text\n   anchors and POSIX bracket names are accepted by one engine and either refused\n   or read DIFFERENTLY by the next, so two conformant validators both compile\n   the pattern and then disagree about which payloads match it, with nothing\n   logged. `\\s` and `\\B` are the plainest examples — RE2 reads `\\s` as\n   [\\t\\n\\f\\r ], Python adds the vertical tab, and ECMA-262 adds that plus every\n   Unicode space separator; `\\B` finds no word boundary in the empty string for\n   RE2 and ECMA-262 and finds one for Python. An explicit character class says\n   what was meant and means it everywhere.\n\n   Where a pattern may appear. `pattern` states its regex as a value and\n   `patternProperties` states its regexes as KEYS; both are patterns and both\n   are held to the alphabet above. They are the only two keywords in the dialect\n   that carry one — `propertyNames` reaches the rule through the subschema it\n   applies.\n\n   No nested quantifiers. A quantified group MUST NOT have a body that can\n   itself repeat or branch: `(a+)+`, `(a|a)*` and `([a-z]+)*` are refused, while\n   `(?:ab)+` is admitted. This is the denial-of-service half of the pattern\n   rule, and it is deliberately SEPARATE from the alphabet above, because\n   excluding lookaround and backreferences does not cover it — catastrophic\n   backtracking needs neither. It has to be a publishing rule rather than a\n   runtime bound: a regex spin holds its interpreter, so a consumer cannot\n   reliably interrupt one it has already started.\n\n   Annotations stay annotations. A consumer MUST NOT assert format,\n   contentEncoding or contentMediaType. Libraries default differently on each,\n   and a schema whose verdict depends on which library read it has no single\n   answer.\n\n The value MUST be a JSON object. Draft 2020-12 also admits a bare boolean as a\n schema, but this field is a Struct and cannot carry one.\n\n A consumer that finds a schema breaking any of these MUST refuse it, and MUST\n then SKIP its local pre-check rather than repair or truncate the schema —\n leaving the Exchange's own enforcement the deciding check, exactly as when no\n schema is published. Refusing locally and declining to send would turn a rule\n about reading a third party's document into a denial of service against the\n consumer's own user. That is the CLIENT side. An Exchange that cannot compile\n its OWN configured schema is looking at a misconfiguration of its deployment,\n and MUST NOT advertise a schema it is not itself enforcing.").optional() }).describe("Exchange-only. How to open an account here — see AccountRegistration, which\n owns the contract. Absent: registration_data is accepted uninspected,\n exactly as before this field existed.").optional(), "base_currency": z.string().describe("Exchange-only. Base currency for pricing (ISO 4217). All unit_cost\n values from this Exchange are denominated in this currency.").optional(), "catalog_contributors": z.array(z.object({ "domain": z.string().describe("Canonical domain of the authorized contributor (e.g., \"doubleverify.com\").").default(""), "relationship": z.string().describe("Relationship of this contributor to the provider.\n Examples: \"verifier\" (resource intelligence vendor that attests to resource\n properties), \"exchange\" (an Exchange that enriches catalog entries).").default("") }).describe("CatalogContributor — A third party authorized to push catalog metadata\n (including attestations) on behalf of a provider.")).describe("Publisher-only. Authorized third-party catalog contributors.\n MUST be empty for non-publisher roles.").optional(), "catalog_endpoint": z.string().describe("Exchange-only. CatalogService endpoint URL (if exposed).").optional(), "contact": z.string().describe("Contact email (licensing, integration, security).").optional(), "delivery_methods_supported": z.array(z.enum(["DELIVERY_METHOD_DIRECT","DELIVERY_METHOD_INSTRUCTIONS","DELIVERY_METHOD_STREAMING"])).describe("Exchange-only. Supported delivery methods.").optional(), "domain": z.string().describe("Canonical domain serving this manifest.").default(""), "endpoint": z.string().describe("Exchange-only. ExchangeService endpoint URL. MUST be on the same host AND\n PORT that serve this manifest, or on a subdomain of that host on that port,\n and MUST NOT carry userinfo. A consumer refuses an endpoint anywhere else:\n this document is only as trustworthy as the host that served it, so an\n endpoint naming an unrelated host would let whoever answers for the manifest\n redirect a signed call to a party the signature never covered, and another\n port is another service the publisher of the manifest need not control. The\n host match is on a full dot-delimited label boundary, so evil-a.com is not a\n subdomain of a.com. A port equal to the scheme's default and an omitted port\n are the SAME port, so https://x, https://x:443 and x all match. An Exchange\n reachable on a non-default port names that port on both sides.").optional(), "exchanges": z.array(z.object({ "domain": z.string().regex(new RegExp("^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?(\\.[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?)*(:(6553[0-5]|655[0-2][0-9]|65[0-4][0-9]{2}|6[0-4][0-9]{3}|[1-5][0-9]{4}|[1-9][0-9]{0,3}))?$")).max(260).describe("Canonical domain of the Exchange, in the shape \"Request recipient\" defines\n in the file header."), "endpoint": z.string().describe("RAMP ExchangeService endpoint URL.").default(""), "ext": z.record(z.string(), z.any()).describe("Extension point").optional(), "ext_critical": z.array(z.string()).describe("Critical extension keys (COSE crit pattern, RFC 9052).\n Lists keys within ext that the consumer MUST understand.\n Unknown keys in this list → reject with UNKNOWN_CRITICAL_EXTENSION.\n Empty (default) → all ext keys are safe to ignore.").optional(), "relationship": z.enum(["PROVIDER_RELATIONSHIP_DIRECT","PROVIDER_RELATIONSHIP_RESELLER"]).describe("Relationship type (mirrors ads.txt DIRECT/RESELLER).") }).describe("AuthorizedExchange — A Exchange authorized to sell this provider's resources.")).describe("Publisher-only. Authorized exchanges for this publisher's resources.\n Like ads.txt — declares who may sell. MUST be empty for non-publisher\n roles.").optional(), "ext": z.record(z.string(), z.any()).describe("Extension point").optional(), "ext_critical": z.array(z.string()).describe("Critical extension keys (COSE crit pattern, RFC 9052). Lists keys\n within ext that the consumer MUST understand. Unknown values reject\n with UNKNOWN_CRITICAL_EXTENSION. Empty (default) → ignore-unknown.").optional(), "gnap_grant_endpoint": z.string().describe("Exchange-only. GNAP grant endpoint when GNAP is supported.").optional(), "hash_methods_supported": z.array(z.string()).describe("Exchange-only. Accepted resource hash methods for attestation\n verification.").optional(), "health_endpoint": z.string().describe("Exchange-only. Health check endpoint URL.").optional(), "max_intermediary_hops": z.coerce.number().int().gte(-2147483648).lte(2147483647).describe("Exchange-only. Maximum forwarding hops this Exchange tolerates on an inbound\n request (Agent → Broker → … → Exchange), counted as RFC 9421 HTTP Message\n Signatures. A request carrying more SHOULD be rejected. Lets Exchanges\n publish their chain-depth tolerance so Brokers prune before forwarding.\n Absent = no published limit (Exchange applies its own default policy).").optional(), "name": z.string().describe("Exchange-only. Human-readable Exchange name.").optional(), "oidc_issuer": z.string().describe("Exchange-only. OIDC Discovery URL when OAuth methods are supported.").optional(), "operator": z.string().describe("Exchange-only. Organization operating this Exchange.").optional(), "operator_domain": z.string().describe("Exchange-only. Operator's corporate domain (may differ from domain).").optional(), "pricing_models_supported": z.array(z.enum(["PRICING_MODEL_FREE","PRICING_MODEL_PER_UNIT","PRICING_MODEL_FLAT"])).describe("Exchange-only. Supported pricing models.").optional(), "privacy_uri": z.string().describe("Exchange-only. Privacy policy URL.").optional(), "protocol_versions_supported": z.array(z.string()).describe("Exchange-only. Supported RAMP protocol versions (e.g. [\"1.0\"]).").optional(), "role": z.enum(["ROLE_AGENT","ROLE_EXCHANGE","ROLE_BROKER","ROLE_PUBLISHER"]).describe("Role this manifest describes."), "supported_auth_methods": z.array(z.enum(["AUTH_METHOD_GNAP","AUTH_METHOD_OAUTH_DPOP","AUTH_METHOD_OAUTH_BEARER","AUTH_METHOD_OAUTH_MTLS"])).describe("Exchange-only. Authorization methods this Exchange supports\n (ordered by preference).").optional(), "supported_profiles": z.array(z.string()).describe("Exchange-only. Domain extension profiles this Exchange conforms to.\n See standards-layering docs.").optional(), "terms_digest": z.string().regex(new RegExp("^(sha256:[0-9a-f]{64}|sha384:[0-9a-f]{96}|sha512:[0-9a-f]{128})?$")).describe("Exchange-only. Digest of the document served at `terms_uri`, in\n \"method:hexdigest\" form (e.g. \"sha256:9f86d081...\"), pinning WHICH terms\n document this manifest is currently offering. `terms_uri` alone cannot\n answer that: it is a URL, and its content changes, so after the first\n revision every earlier registration points at a document that no longer says\n what was agreed. RegisterRequest.terms_digest echoes this value, the request\n signature covers that echo, and the Exchange records the accepted digest\n with the account — which is what makes \"which terms did this operator\n accept\" answerable later, through GetAccountStatusResponse.terms_digest, which\n is where the accepted value is read back. Because a digest identifies a\n document only while\n a copy of it still exists, keeping the historical terms documents\n retrievable is the Exchange's obligation. It sits at the top level rather\n than inside account_registration on purpose: an Exchange with pass-through\n registration publishes no block yet still needs to pin its terms version,\n and coupling \"I enforce a schema\" to \"I version my terms\" would tie together\n two independent decisions. Operator note: publishing this field for the\n first time refuses every client that does not yet echo it, so it is a\n coordinated change rather than a safe addition.").optional(), "terms_uri": z.string().describe("Exchange-only. Terms of service URL.").optional(), "ver": z.string().describe("RAMP protocol version of THIS MANIFEST DOCUMENT's schema — a namespace\n separate from the RPC envelope `ver`, deliberately not coupled to it.\n MUST equal \"1.0\"; consumers REJECT unrecognised major versions.").default("") }).describe("WellKnownManifest — RAMP commercial overlay, served at /.well-known/ramp.json\n by every RAMP participant (agent, exchange, broker, publisher).\n\nCommercial graph only: role, authorized exchanges/contributors, and exchange\n capability fields. Identity keys are NOT here — they live in the WBA directory\n (WBAFile) served at /.well-known/http-message-signatures-directory and are\n referenced by RFC 7638 thumbprint, never republished here.\n Per-role fields are populated only when that role applies; consumers\n MUST ignore non-applicable fields based on `role`."));

